"""Render HTML asset studies from actual pack sources; optional browser screenshots are separate."""
from pathlib import Path
import argparse,html,json,shutil,sys
from build_illustrated_collection import COLLECTION,ROOT
LABELS={'header':'Home & deep-screen artwork','player':'Player artwork','preview':'Studio preview','brandIcon':'In-app Veyra brand','headingFont':'Heading font','bodyFont':'Manrope · body font','nav_home':'Home','nav_search':'Search','nav_explore':'Explore','nav_library':'Library','play':'Play','pause':'Pause','previous':'Previous','next':'Next','queue':'Queue','lyrics':'Lyrics','settings':'Settings','back':'Back','download':'Download'}
CSS='''*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Body,sans-serif}main{max-width:1280px;margin:auto;padding:48px 40px}h1,h2,h3{font-family:Heading;font-weight:600}h1{font-size:70px;margin:10px 0;line-height:1.05}h2{font-size:36px;margin:32px 0 18px}h3{font-size:24px;margin:12px 0 5px}p{color:var(--muted);line-height:1.7;max-width:900px}.eyebrow{color:var(--accent);font-size:12px;letter-spacing:2px;text-transform:uppercase}.intro{display:flex;align-items:center;justify-content:space-between;border-bottom:1px dashed var(--outline);padding-bottom:22px;gap:20px}.intro img{width:128px}.palette{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}.swatch{border:1px solid var(--outline);border-radius:12px;padding:12px;font-size:11px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.asset{border:1px solid var(--outline);background:var(--surface);border-radius:17px 11px 19px 13px;padding:16px}.wide{grid-column:span 2}.sample{height:120px;display:flex;align-items:center;justify-content:center;background:var(--bg);border-radius:12px;overflow:hidden}.wide .sample{height:270px}.art{width:100%;height:100%;object-fit:cover;object-position:center 69%}.glyph{width:66px;height:66px}.brand{width:100px;height:100px}code{font-size:10px;color:var(--muted);overflow-wrap:anywhere}.heading{font-family:Heading;font-size:44px;line-height:1.1}.body{font-family:Body;font-size:31px}.font{padding:28px}.font small{display:block;margin-top:16px;font-size:18px}.pill{display:inline-block;padding:7px 12px;border:1px solid var(--secondary);border-radius:15px;color:var(--secondary);font-size:11px}.demo{padding:25px;border:1px solid var(--outline);border-radius:28px 20px 30px 22px;background:var(--surface)}.controls{display:flex;align-items:center;justify-content:center;gap:22px;margin:24px}.control{border:1px solid var(--outline);background:var(--raised);border-radius:35% 39% 34% 37%;width:70px;height:70px;cursor:pointer;transition:transform 140ms cubic-bezier(.2,0,0,1)}.control img{width:34px}.primary{background:var(--container);width:90px;height:90px}.control:active{transform:rotate(-2.5deg) scale(.95)}.navbar{display:flex;justify-content:space-around;border:1px solid var(--outline);border-radius:23px;padding:10px}.nav{border:0;background:transparent;color:var(--text);font-family:Heading;font-size:15px;cursor:pointer;min-height:48px;padding:8px}.nav img{display:block;width:26px;height:26px;margin:auto auto 5px}.nav.active{background:var(--container);border-radius:17px}.seek{height:8px;border:1px solid var(--outline);border-radius:5px;background:repeating-linear-gradient(120deg,var(--raised) 0 6px,var(--secondary) 7px 8px)}.seek:before{content:'';display:block;background:var(--accent);width:38%;height:100%;border-radius:4px}.note{font-size:12px}.footer{border-top:1px dashed var(--outline);padding-top:20px;margin-top:28px}a{color:var(--accent)}@media(max-width:720px){main{padding:25px 16px}h1{font-size:50px}.intro img{width:80px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.wide{grid-column:span 2}}@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}'''

def theme_page(c,prefix):
 m=json.loads((ROOT/c['id']/'theme.json').read_text());a=m['assets'];p=m['palette']
 fonts=f"@font-face{{font-family:Heading;src:url({prefix}{a['headingFont']})}}@font-face{{font-family:Body;src:url({prefix}{a['bodyFont']})}}"
 vars=':root{'+''.join('--'+{'background':'bg','accentContainer':'container'}.get(k,k)+':'+v+';' for k,v in p.items())+'}'
 cards=[]
 for key,path in a.items():
  wide=key in ['header','player','preview','headingFont','bodyFont']
  if key.endswith('Font'):
   sample=f'<div class="font {"heading" if key=="headingFont" else "body"}">Little worlds.<br>Favourite songs.<small>Aa Bb Cc · 0123456789</small></div>'
  else:sample=f'<img src="{prefix}{path}" class="{"art" if key in ["header","player","preview"] else "brand" if key=="brandIcon" else "glyph"}" alt="{html.escape(LABELS[key])}">'
  cards.append(f'<article class="asset {"wide" if wide else ""}"><div class="sample">{sample}</div><h3>{html.escape(LABELS[key])}</h3><code>{key} → {path}</code></article>')
 controls=''.join(f'<button class="control {"primary" if key=="play" else ""}" aria-label="{LABELS[key]}"><img src="{prefix}{a[key]}" alt=""></button>' for key in ['previous','play','next'])
 nav=''.join(f'<button class="nav"><img src="{prefix}{a[key]}" alt="">{LABELS[key]}</button>' for key in ['nav_home','nav_search','nav_explore','nav_library'])
 palette=''.join(f'<span class="swatch" style="border-bottom:6px solid {value}">{key}<br>{value}</span>' for key,value in p.items())
 behavior='Uneven paper shapes · pencil-hatched seek · press tilt · paper slide' if c['scene']=='sketch' else 'Rounded controls · bubble seek · playful spring press'
 js="""document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>{document.querySelectorAll('.nav').forEach(n=>n.classList.remove('active'));b.classList.add('active')});"""
 if c['scene']=='playful':js+="""document.querySelectorAll('.control').forEach(b=>b.onclick=()=>{if(!matchMedia('(prefers-reduced-motion:reduce)').matches)b.animate([{transform:'scale(1)'},{transform:'scale(.92)'},{transform:'scale(1.025)'},{transform:'scale(1)'}],{duration:280})});"""
 return f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(c['name'])} · every asset</title><style>{fonts}{vars}{CSS}</style><main><div class="intro"><div><span class="eyebrow">Veyra · Illustrated Worlds · {c['medium']}</span><h1>{html.escape(c['name'])}</h1><p>{c['tagline']}</p><span class="pill">Beta 0.1.9 · supported engine build 30</span></div><img src="{prefix}{a['brandIcon']}" alt="Themed Veyra brand"></div><div class="palette">{palette}</div><h2>01 / All 19 asset roles</h2><p>{html.escape(c['description'])} One coherent illustration intentionally serves Home, Player and Studio. Every role is shown; the shared artwork is one file, not three separate illustrations. Transparent functional glyphs receive the theme tint in Veyra.</p><div class="grid">{''.join(cards)}</div><h2>02 / Component design study</h2><div class="demo"><h3>{c['tagline']}</h3><div class="seek"></div><div class="controls">{controls}</div><div class="navbar">{nav}</div><p class="note">{behavior}. These are supported native presets, not five new animation engines. This browser composition uses actual pack assets and is not an Android screenshot.</p></div><footer class="footer"><p>Original AI illustration + original functional vector glyphs. Fonts and OFL notices are included. The brand is an in-app mark; launcher aliases remain unchanged. App animation settings remain respected. Actual device FPS has not been measured.</p></footer></main><script>{js}</script></html>'''

def overview(prefix):
 fonts='@font-face{font-family:Body;src:url('+prefix('lantern-letters','fonts/Manrope.ttf')+')}@font-face{font-family:Hand;src:url('+prefix('lantern-letters','fonts/PatrickHand.ttf')+')}'
 cards=[]
 for c in COLLECTION:
  m=json.loads((ROOT/c['id']/'theme.json').read_text());p=m['palette'];a=m['assets'];font='F'+c['id'].replace('-','')
  fonts+=f'@font-face{{font-family:{font};src:url({prefix(c["id"],a["headingFont"])})}}'
  swatches=''.join(f'<span style="background:{v}"></span>' for v in [p['background'],p['raised'],p['accent'],p['secondary'],p['text']])
  glyphs=''.join(f'<img src="{prefix(c["id"],a[k])}" alt="{LABELS[k]}">' for k in ['nav_home','nav_search','nav_explore','nav_library','play'])
  cards.append(f'''<article style="--surface:{p['surface']};--accent:{p['accent']};--text:{p['text']};--muted:{p['muted']}"><img class="world" src="{prefix(c['id'],a['header'])}" alt="{html.escape(c['name'])} illustration"><div class="cardbody"><div class="title"><h2 style="font-family:{font}">{html.escape(c['name'])}</h2><img class="badge" src="{prefix(c['id'],a['brandIcon'])}" alt="Theme brand"></div><small>{c['medium']}</small><p>{c['tagline']}</p><div class="swatches">{swatches}</div><div class="glyphs">{glyphs}</div><span class="preset">{'Paper slide + pencil press' if c['scene']=='sketch' else 'Playful spring press'}</span></div></article>''')
 return f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Illustrated Worlds · five Veyra themes</title><style>{fonts}*{{box-sizing:border-box}}body{{margin:0;background:#171b20;color:#fff5e8;font-family:Body}}main{{padding:45px 38px;max-width:2000px;margin:auto}}.eyebrow{{color:#d9c6a0;letter-spacing:3px;font-size:11px}}h1{{font-family:Hand;font-size:68px;font-weight:400;margin:8px 0}}header p{{color:#c3beb7;font-size:14px;line-height:1.7}}.worlds{{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:17px;margin-top:30px}}article{{background:var(--surface);border:1px solid #ffffff2b;border-radius:19px;overflow:hidden;color:var(--text)}}.world{{width:100%;height:455px;object-fit:cover;display:block}}.cardbody{{padding:17px}}.title{{display:flex;align-items:center;gap:8px;min-height:83px}}h2{{font-weight:600;font-size:33px;line-height:1.05;flex:1;margin:0}}.badge{{width:48px;height:48px}}small{{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:var(--accent)}}article p{{font-size:12px;line-height:1.6;color:var(--muted);min-height:39px}}.swatches{{display:flex;gap:5px;margin:17px 0}}.swatches span{{height:12px;flex:1;border-radius:8px;border:1px solid #ffffff35}}.glyphs{{display:flex;justify-content:space-between;margin:20px 0}}.glyphs img{{width:26px;height:26px}}.preset{{font-size:10px;color:var(--accent)}}footer{{margin-top:24px;color:#bdb6aa;font-size:11px;line-height:1.7}}@media(max-width:950px){{.worlds{{grid-template-columns:repeat(2,1fr)}}main{{padding:25px 16px}}h1{{font-size:48px}}.world{{height:auto;aspect-ratio:2/3}}}}</style><main><header><span class="eyebrow">VEYRA · ILLUSTRATED WORLDS · COLLECTION 01</span><h1>Five little universes. Yours to play.</h1><p>Ink & watercolor / retro risograph / botanical engraving / hand-painted gouache / layered cut paper<br>Five original illustrations · 65 functional glyphs · five themed brand marks · supported build-30 presets</p></header><section class="worlds">{''.join(cards)}</section><footer>Actual theme assets, fonts and palettes. Collection study, not Android screenshots. Each theme has a complete 19-role asset gallery and licensed fonts.<br>Compatible with beta 0.1.9 build 30. No new engine rebuild is needed if that build is already installed. Stable 0.1.8 is unchanged.</footer></main></html>'''

def render(out):
 out=Path(out);out.mkdir(parents=True,exist_ok=True)
 for c in COLLECTION:
  folder=out/c['id'];shutil.copytree(ROOT/c['id'],folder/'assets',dirs_exist_ok=True);shutil.copytree(ROOT/'source-icons'/c['id'],folder/'vectors',dirs_exist_ok=True)
  shutil.copyfile(ROOT/'packs'/f'{c["id"]}-v1.zip',folder/f'{c["id"]}-v1.zip');shutil.copyfile(ROOT/'packs'/f'{c["id"]}-v1.zip.sha256',folder/f'{c["id"]}-v1.zip.sha256')
  (folder/'index.html').write_text(theme_page(c,'assets/'))
  repo=ROOT/'previews'/c['id'];repo.mkdir(parents=True,exist_ok=True);(repo/'index.html').write_text(theme_page(c,'../../'+c['id']+'/'))
 (out/'index.html').write_text(overview(lambda key,path:key+'/assets/'+path))
 repo=ROOT/'previews/illustrated-worlds';repo.mkdir(parents=True,exist_ok=True);(repo/'index.html').write_text(overview(lambda key,path:'../../'+key+'/'+path))
if __name__=='__main__':
 parser=argparse.ArgumentParser();parser.add_argument('output',type=Path);args=parser.parse_args();render(args.output)
